<script lang="ts">
 import {onMount} from 'svelte';
 import * as api from '../../bindings';
 import type {CaseOperations} from '../operations/controller.svelte';
 import PackageForm from '../operations/PackageForm.svelte';
 import ErrorNotice from '../../ErrorNotice.svelte';
 interface Citation{kind:string;id:string;role:string;}
 interface Finding{heading:string;text:string;citations:Citation[];}
 let {generation,operations,selected,active}:{generation:number;active:boolean;operations:CaseOperations;selected:{kind:string;id:string}|null}=$props();
 let mapImages=$state<api.MapIllustrationView[]>([]),mapIds=$state<string[]>([]);
 let reports=$state<api.WorkspaceSummaryView[]>([]),loaded=$state<api.WorkspaceView|null>(null),title=$state('Investigation report'),summary=$state(''),limitations=$state(''),findings=$state<Finding[]>([{heading:'Finding',text:'',citations:[]}]),boards=$state<api.WorkspaceSummaryView[]>([]),boardIds=$state<string[]>([]),role=$state('supports'),error=$state<api.CommandError|null>(null),busy=$state(false),message=$state(''),offset=$state(0),total=$state(0);let boardTotal=$state(0);let previewSignature=$state('');let draftSignature=$derived(JSON.stringify([title,summary,limitations,findings,boardIds,mapIds]));let live=true,version=0;
 onMount(()=>{void refresh();return()=>{live=false;version++;};});
 export async function refresh(){try{const [page,boardPage,images]=await Promise.all([api.workspacePage(generation,'report',offset),api.workspacePage(generation,'board'),api.mapIllustrations(generation)]);if(live){mapImages=images;reports=page.rows;total=page.total;boards=boardPage.rows;boardTotal=boardPage.total;}}catch(raw){if(live)error=api.asCommandError(raw);}}
 async function moreBoards(){try{const page=await api.workspacePage(generation,'board',boards.length);if(live){boards=[...boards,...page.rows];boardTotal=page.total;}}catch(raw){if(live)error=api.asCommandError(raw);}}
 async function load(id:string){const current=++version;try{const row=await api.workspaceRead(generation,id);if(!live||current!==version)return;if(row.payload.version!==1||!Array.isArray(row.payload.findings)||row.payload.findings.some(f=>!f||typeof f.heading!=='string'||typeof f.text!=='string'||!Array.isArray(f.citations)))throw new Error('The saved report structure is invalid.');loaded=row;title=row.name;summary=String(row.payload.summary??'');limitations=String(row.payload.limitations??'');findings=(row.payload.findings as Finding[])??[];boardIds=(row.payload.boards as string[])??[];mapIds=(row.payload.map_illustrations as string[])??[];message='Draft loaded.';}catch(raw){if(live)error=api.asCommandError(raw);}}
 export function appendSuggestion(s:api.AiSuggestionView){findings=[...findings,{heading:'Human-reviewed local AI suggestion',text:`Local model ${s.model}: ${s.text}`,citations:s.cited_observation_ids.map(id=>({kind:'observation',id,role:'context'}))}];message='Reviewed suggestion added as an editable finding. Validate its evidence before exporting.';}
 export function cite(kind:string,id:string){if(!['observation','entity','identifier','relationship'].includes(kind))return;if(!findings.length)findings=[{heading:'Finding',text:'',citations:[]}];const target=findings[findings.length-1];if(!target.citations.some(c=>c.kind===kind&&c.id===id&&c.role===role))target.citations=[...target.citations,{kind,id,role}];message='Citation added to the last finding. Review it before export.';}
 async function save(archive=false):Promise<api.WorkspaceView|null>{if(busy||operations.busy)return null;busy=true;error=null;try{const row=await api.workspaceSave(generation,{id:loaded?.id??crypto.randomUUID(),kind:'report',name:title,expected_revision:loaded?.revision??0,payload:{version:1,summary,limitations,findings:$state.snapshot(findings),boards:[...boardIds],map_illustrations:[...mapIds]},archived:archive});if(!live)return null;loaded=row;message=archive?'Report archived; revisions retained.':`Saved revision ${row.revision}.`;await refresh();return row;}catch(raw){if(live)error=api.asCommandError(raw);return null;}finally{if(live)busy=false;}}
 async function preview(){const saved=await save();if(saved&&live){previewSignature=draftSignature;await operations.run('report_preview',{report_id:saved.id,revision:saved.revision});}}
 async function exportReport(format:'markdown'|'html'){const saved=await save();if(!saved||!live)return;try{const destination=await api.selectPath(format==='html'?'report_html':'report_markdown',generation);if(destination&&live)await operations.run('report_export',{report_id:saved.id,revision:saved.revision,destination,format});}catch(raw){if(live)error=api.asCommandError(raw);}}
 function fresh(){version++;loaded=null;title='Investigation report';summary='';limitations='';findings=[{heading:'Finding',text:'',citations:[]}];boardIds=[];mapIds=[];message='';}
</script>
<section class="report-workspace" aria-labelledby="export-workspace-title"><header><h3 id="export-workspace-title">Export</h3><button type="button" disabled={busy} onclick={fresh}>New report</button></header>
 {#if error}<ErrorNotice {error}/>{/if}{#if message}<p role="status">{message}</p>{/if}
 <details><summary>Saved reports ({total})</summary>{#each reports as report}<button type="button" disabled={busy} onclick={()=>void load(report.id)}>{report.name} · revision {report.revision}</button>{/each}<button type="button" disabled={offset===0} onclick={()=>{offset-=50;void refresh();}}>Previous reports</button><button type="button" disabled={offset+50>=total} onclick={()=>{offset+=50;void refresh();}}>Next reports</button></details>
 {#if operations.busy}<p role="status">A case operation is in progress. Draft saves are paused until the operation and its consistent snapshot finish.</p>{/if}
 <h4>Readable investigation report</h4><p>Drafts stay encrypted in this case. Markdown and HTML exports contain plaintext. They are reports, not restorable case packages or digital signatures. PDF is not available.</p>
<details><summary>Cited map illustrations ({mapImages.length}; latest 100)</summary>{#each mapImages as image}<label class="check"><input type="checkbox" checked={mapIds.includes(image.id)} onchange={e=>mapIds=e.currentTarget.checked?[...mapIds,image.id]:mapIds.filter(id=>id!==image.id)}/>{image.created_utc} · {image.attribution}</label>{/each}<p>Images are analyst-rendered context. Their location observations are re-checked at export.</p></details>
 <form onsubmit={e=>{e.preventDefault();void save();}}><label>Report title<input required maxlength="120" bind:value={title}/></label><label>Summary<textarea bind:value={summary}></textarea></label>
 {#each findings as finding,i}<fieldset><legend>Finding {i+1}</legend><label>Finding heading<input bind:value={finding.heading}/></label><label>Analyst finding<textarea bind:value={finding.text}></textarea></label><ul>{#each finding.citations as citation,j}<li>{citation.role}: {citation.kind} {citation.id}<button type="button" onclick={()=>finding.citations=finding.citations.filter((_,index)=>index!==j)}>Remove citation</button></li>{/each}</ul><button type="button" onclick={()=>findings=findings.filter((_,index)=>index!==i)}>Remove finding</button></fieldset>{/each}
 <button type="button" onclick={()=>findings=[...findings,{heading:'Finding',text:'',citations:[]}]}>Add finding</button>
 <label>Citation role<select bind:value={role}><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="context">Context</option></select></label><button type="button" disabled={!selected||!['observation','entity','identifier','relationship'].includes(selected.kind)} onclick={()=>selected&&cite(selected.kind,selected.id)}>Cite selected record</button>
 <p>Open an observation or analytical record, inspect its source, then use “Add to report”. Every exported finding needs a citation; unavailable evidence is explicitly reported.</p>
 <label>Limitations and uncertainty<textarea bind:value={limitations}></textarea></label><fieldset><legend>Graph illustrations</legend><p>Include at most 20 saved boards per report.</p>{#each boards as board}<label class="check"><input type="checkbox" value={board.id} bind:group={boardIds}/>{board.name}</label>{/each}{#if !boards.length}<p>Save a graph board to include it in a report.</p>{/if}{#if boards.length<boardTotal}<button type="button" onclick={()=>void moreBoards()}>More graph boards ({boards.length} of {boardTotal})</button>{/if}</fieldset>
 <button disabled={busy||operations.busy}>Save report draft</button>{#if loaded}<button type="button" disabled={busy||operations.busy} onclick={()=>void save(true)}>Archive report</button>{/if}
 <button type="button" disabled={busy||operations.busy} onclick={()=>void preview()}>Validate and preview report</button>
 <button type="button" disabled={busy||operations.busy||!findings.length||findings.some(f=>!f.citations.length)} onclick={()=>void exportReport('markdown')}>Export Markdown report</button><button type="button" disabled={busy||operations.busy||!findings.length||findings.some(f=>!f.citations.length)} onclick={()=>void exportReport('html')}>Export HTML report</button></form>
 {#if loaded&&previewSignature===draftSignature&&operations.result?.report_id===loaded.id&&operations.result?.revision===loaded.revision&&typeof operations.result.content==='string'}<details open><summary>Validated report preview</summary><pre>{operations.result.content}</pre></details>{/if}
 {#if active}<details><summary>Encrypted packages, verification and restore</summary><p>Packages preserve case identities, lineage, boards and report revisions. There is no package recovery key or digital signature. Exclusions and missing evidence remain accounted for. Restore creates a new case directory.</p><PackageForm bind:passphrase={operations.passphrase} bind:exclusions={operations.exclusions} busy={operations.busy} onsubmit={operations.exportCase} onverify={operations.verify} onrestore={operations.restore}/></details>{/if}
</section>
<style>section{padding:24px;border:1px solid var(--border);border-radius:var(--radius-panel);background:var(--surface-panel)}header{display:flex;align-items:center;gap:12px}h3{font-size:28px;margin:0 auto 0 0}form,label{display:grid;gap:8px}form{gap:16px}fieldset{min-width:0;border:1px solid var(--border);padding:16px}.check{display:flex;align-items:center}textarea{min-height:80px;resize:vertical}details{margin:24px 0}li{overflow-wrap:anywhere}p{max-width:75ch}pre{white-space:pre-wrap;overflow-wrap:anywhere}li button,details>button{margin:8px}</style>
